/* Clientes físicos com cesta reservada e pagamento exclusivamente no caixa. */
const CHECKOUT=[560,330],QUEUE=[[700,230],[700,290],[700,350],[700,410],[620,370],[550,390]];
const customerInitial=initial;initial=function(){let v=customerInitial();v.stock.baskets=0;v.customers=[];v.nextCustomer=1;v.arrival=0;v.closing=false;return v};
s.stock.baskets=0;s.customers=[];s.nextCustomer=1;s.arrival=0;s.closing=false;
const priorCap=cap; // capacidade da cesta é coletiva, não armazenamento acessível
const previousValidation=valid;valid=function(v){if(v&&!v.customers){v.customers=[];v.stock.baskets=0;v.nextCustomer=1;v.arrival=0;v.closing=false}if(!v||!Array.isArray(v.customers)||v.customers.length>6||!Number.isFinite(v.arrival)||!Number.isInteger(v.nextCustomer))return false;let ids=new Set(),held=0;for(let c of v.customers){if(!c||!Number.isInteger(c.id)||ids.has(c.id)||!['street','shop'].includes(c.room)||!['enter','browse','queue','exit','leave'].includes(c.state)||!Array.isArray(c.pos)||c.pos.length!==2||!c.pos.every(Number.isFinite)||typeof c.basket!=='boolean'||!Number.isFinite(c.price)||!Number.isFinite(c.progress)||c.progress<0||c.progress>3||typeof c.serving!=='boolean')return false;ids.add(c.id);held+=Number(c.basket);c.path=[];c.goal=''}return held===v.stock.baskets&&previousValidation(v)};
function atCheckout(){return s.room==='shop'&&Math.hypot(s.player[0]-CHECKOUT[0],s.player[1]-CHECKOUT[1])<65}
function queue(){return s.customers.filter(c=>c.state==='queue')}
function spawnCustomer(){if(s.customers.length>=6)return;let id=s.nextCustomer++;s.customers.push({id,room:'street',pos:[id%2?35:760,350],state:'enter',basket:false,price:0,progress:0,serving:false,path:[],goal:''})}
function customerWalk(c,to,dt){let key=c.room+to.join(',');if(c.goal!==key){c.path=route(c.room,c.pos,to);c.goal=key}if(!c.path)return false;return follow(c.pos,c.path,110,dt)&&Math.hypot(c.pos[0]-to[0],c.pos[1]-to[1])<4}
$('serve').onclick=()=>{if(!atCheckout())return say('Toque no balcão para se aproximar do caixa e então Atender.',true);let c=queue()[0];if(!c)return say('Nenhum cliente na fila.');if(Math.hypot(c.pos[0]-QUEUE[0][0],c.pos[1]-QUEUE[0][1])>8)return say('O primeiro cliente está chegando ao caixa.');if(c.serving)return say('Atendimento em andamento. Permaneça junto ao caixa.');c.serving=true;say('Registrando a compra do cliente '+c.id+'…')};
const previousShop=$('shop').onclick;
$('shop').onclick=()=>{if(s.open){if(s.closing)return say('Finalize os clientes presentes para concluir o fechamento.');s.closing=true;say('Entrada encerrada. Atenda a fila; o dia fecha quando todos saírem.');if(!s.customers.length)finishClosing()}else{previousShop();s.closing=false;s.arrival=2;say('Loja aberta. Clientes chegam pela rua. Vá ao caixa para atendê-los.')}};
function finishClosing(){s.closing=false;previousShop()}
const simulationStep=step;step=function(dt){simulationStep(dt);if(s.open&&!s.closing){s.arrival+=dt;if(s.arrival>=4+s.price){s.arrival=0;spawnCustomer()}}let line=queue();for(let c of s.customers){if(c.state==='enter'&&customerWalk(c,[400,310],dt)){c.room='shop';c.pos=[400,370];c.state='browse';c.goal=''}else if(c.state==='browse'&&customerWalk(c,[280,280],dt)){if(s.stock.sales){s.stock.sales--;s.stock.baskets++;c.basket=true;c.price=s.price;c.state='queue';c.goal=''}else{s.missed++;c.state='exit';c.goal='';say('Cliente '+c.id+' não encontrou produto e está saindo.')}}else if(c.state==='queue'){let index=line.indexOf(c);if(index<0)continue;let reached=customerWalk(c,QUEUE[index],dt);if(index===0&&reached&&c.serving&&atCheckout()){c.progress=Math.min(3,c.progress+dt);if(c.progress>=3){s.stock.baskets--;s.sold++;s.cash+=c.price*6;s.revenue+=c.price*6;s.cost+=6;c.basket=false;c.serving=false;c.state='exit';c.goal='';say('Venda concluída! +$'+(c.price*6).toFixed(2)+'. Atenda o próximo cliente.')}}}else if(c.state==='exit'&&customerWalk(c,[400,410],dt)){c.room='street';c.pos=[400,340];c.state='leave';c.goal=''}else if(c.state==='leave'&&customerWalk(c,[c.id%2?35:760,350],dt))c.done=true}
s.customers=s.customers.filter(c=>!c.done);if(s.closing&&!s.customers.length)finishClosing();checkoutUI();update()};
function checkoutUI(){let line=queue(),c=line[0];$('checkoutStatus').textContent=`Clientes na loja/rua: ${s.customers.length} • Fila: ${line.length}`+(c?.serving?` • ${atCheckout()?'Registrando':'Pausado: volte ao caixa'} ${Math.floor(c.progress/3*100)}%`:'');$('serve').textContent=c?.serving?'Atendendo… permaneça no caixa':'Atender no caixa';if(s.closing)$('shop').textContent='Fechando • conclua os atendimentos'}
const sceneDraw=draw;draw=function(){sceneDraw();for(let c of s.customers){if(c.room!==s.room)continue;person(c.pos,['#b77f9f','#718db5','#c68c58'][c.id%3],c.state==='queue'?(c.serving?(typeof checkoutFeedback==='function'&&checkoutFeedback(c).startsWith('Atendimento pausado')?'Pausado':'Atendendo'):'Fila '+(queue().indexOf(c)+1)):'Cliente '+c.id,c.basket);if(c.serving){rect(c.pos[0]-25,c.pos[1]-45,50,5,'#675d51');rect(c.pos[0]-25,c.pos[1]-45,50*c.progress/3,5,'#65ac75')}}if(s.room==='shop'){text('ATENDIMENTO',CHECKOUT[0],CHECKOUT[1]+25,13,'#375446');for(let p of QUEUE){ctx.strokeStyle='#77695055';ctx.beginPath();ctx.arc(p[0],p[1],13,0,Math.PI*2);ctx.stroke()}}};
checkoutUI();say('Clientes precisam pagar no caixa. Abasteça o expositor, abra a loja e toque no balcão para atender.');
